// Terms / privacy acceptance (docs/legal/README.md, "For app integrators"): the bundled
// `Legal/legal.json` (generated by tools/legal.py, never hand-edited) gives the version, the
// modal texts (it/en) and the page names. The accepted version lives in UserDefaults: the app
// and the Share extension each keep their own (no App Group, ADR 0009), so each asks once.
// Foundation only: also compiled into the host-less HoppyTests target.
import Foundation

struct LegalVersion: Codable, Equatable {
    let terms: Int
    let privacy: Int
}

struct LegalTexts: Decodable {
    let version: LegalVersion
    let strings: [String: [String: String]]
    let pages: [String: [String: String]]

    /// "it" when the system's first language is Italian, else "en" (the contract's rule).
    static func language(_ preferred: [String] = Locale.preferredLanguages) -> String {
        (preferred.first ?? "en").lowercased().hasPrefix("it") ? "it" : "en"
    }

    /// The bundled `Legal/legal.json` (a folder reference in project.yml), or nil if broken.
    static func load(bundle: Bundle = .main) -> LegalTexts? {
        guard let url = bundle.url(forResource: "legal", withExtension: "json", subdirectory: "Legal"),
              let data = try? Data(contentsOf: url) else { return nil }
        return try? JSONDecoder().decode(LegalTexts.self, from: data)
    }

    /// A modal string in the user's language (English, then the key, as fallbacks).
    func text(_ key: String, language lang: String = LegalTexts.language()) -> String {
        strings[lang]?[key] ?? strings["en"]?[key] ?? key
    }

    /// File URL of a bundled page ("terms", "privacy", "licenses") in the user's language.
    func page(_ name: String, bundle: Bundle = .main, language lang: String = LegalTexts.language()) -> URL? {
        guard let file = pages[name]?[lang] ?? pages[name]?["en"] else { return nil }
        let base = (file as NSString).deletingPathExtension, ext = (file as NSString).pathExtension
        return bundle.url(forResource: base, withExtension: ext, subdirectory: "Legal")
    }
}

enum LegalConsent {
    private static let termsKey = "hoppy.legal.terms"
    private static let privacyKey = "hoppy.legal.privacy"

    /// The version accepted on this device (app or extension container), nil if never.
    static func stored(_ defaults: UserDefaults = .standard) -> LegalVersion? {
        guard defaults.object(forKey: termsKey) != nil, defaults.object(forKey: privacyKey) != nil else { return nil }
        return LegalVersion(terms: defaults.integer(forKey: termsKey), privacy: defaults.integer(forKey: privacyKey))
    }

    /// Ask when nothing was accepted, when either bundled number is higher, or when the texts
    /// are missing (fail closed: the node never starts without an acceptance).
    static func needsAcceptance(bundled: LegalVersion?, stored: LegalVersion?) -> Bool {
        guard let bundled = bundled else { return true }
        guard let stored = stored else { return true }
        return bundled.terms > stored.terms || bundled.privacy > stored.privacy
    }

    static func needsAcceptance(_ texts: LegalTexts?, defaults: UserDefaults = .standard) -> Bool {
        needsAcceptance(bundled: texts?.version, stored: stored(defaults))
    }

    /// Something was accepted before: the modal shows `updated_title` / `updated_body`.
    static func isUpdate(_ defaults: UserDefaults = .standard) -> Bool { stored(defaults) != nil }

    static func accept(_ version: LegalVersion, defaults: UserDefaults = .standard) {
        defaults.set(version.terms, forKey: termsKey)
        defaults.set(version.privacy, forKey: privacyKey)
    }
}
